public boolean test(Level level, BlockPos origin)
{
    if (this.predicate.isPresent())
    {   return this.predicate.get().test(new BlockInWorld(level, origin, true));
    }

    BlockPos.MutableBlockPos pos = origin.mutable();
    pos.move(this.xOffset, this.yOffset, this.zOffset);

    if (!this.x.test(pos.getX()))
        return false;
    if (!this.y.test(pos.getY()))
        return false;
    if (!this.z.test(pos.getZ()))
        return false;

    if (!this.dimension.test(either -> either.map(tag -> level.dimensionTypeRegistration().is(tag.location()),
                                                  key -> level.dimension().equals(key))))
    {   return false;
    }
    if (!this.biome.test(either -> either.map(tag -> level.getBiomeManager().getNoiseBiomeAtPosition(pos).is(tag),
                                             key -> level.getBiomeManager().getNoiseBiomeAtPosition(pos).is(key))))
    {   return false;
    }
    if (!this.structure.isEmpty())
    {
        StructureManager structureManager = WorldHelper.getServerLevel(level).structureManager();
        if (!this.structure.test(either ->
        {
            StructureStart structureStart = either.map(tag -> structureManager.getStructureWithPieceAt(pos, tag),
                                                       key -> structureManager.getStructureWithPieceAt(pos, key));
            return structureStart != null && structureStart != StructureStart.INVALID_START;
        }))
        {   return false;
        }
    }
    if (!this.light.test(level.getMaxLocalRawBrightness(pos)))
    {   return false;
    }
    if (!this.block.test(level, pos))
    {   return false;
    }
    if (!this.fluid.test(level, pos))
    {   return false;
    }
    if (this.temperature != WorldTempBounds.NONE && !this.temperature.test(WorldHelper.getRoughTemperatureAt(level, pos)))
    {   return false;
    }
    return true;
}

public boolean test(Predicate<T> test)
{
    if (!this.requirements.isEmpty())
    {
        require:
        {
            for (int i = 0; i < this.requirements.size(); i++)
            {
                boolean result = test.test(this.requirements.get(i));
                if (this.requireAll && !result)
                {   return false;
                }
                if (!this.requireAll && result)
                {   break require;
                }
            }
            return this.requireAll;
        }
    }
    if (!this.exclusions.isEmpty())
    {
        for (int i = 0; i < this.exclusions.size(); i++)
        {
            boolean result = test.test(this.exclusions.get(i));
            if (this.excludeAll && !result)
            {   return true;
            }
            if (!this.excludeAll && result)
            {   return false;
            }
        }
        return !this.excludeAll;
    }
    return true;
}

public boolean test(Level level, BlockPos pos, BlockState state)
{
    if (!level.isLoaded(pos)) return true;

    if (!this.blocks.test(either -> either.map(state::is, state::is)))
    {   return false;
    }
    if (!this.state.test(state))
    {   return false;
    }
    if (!this.nbt.isEmpty())
    {
        BlockEntity blockentity = level.getBlockEntity(pos);
        if (blockentity != null && !this.nbt.test(blockentity.saveWithFullMetadata()))
        {   return false;
        }
    }
    if (!this.sturdyFaces.isEmpty() && this.sturdyFaces.stream().noneMatch(face -> state.isFaceSturdy(level, pos, face)))
    {   return false;
    }
    if (this.replaceable.isPresent() && !(state.isAir() || state.canBeReplaced()))
    {   return false;
    }
    return true;
}

