{   return getRoughTemperatureAt(level, pos, 0);
}

public static double getRoughTemperatureAt(Level level, BlockPos pos, int flags)
{
    pos = sublevelToWorld(level, pos);
    boolean sensitive = (flags & 1) != 0;
    boolean forceUpdate = (flags & 2) != 0;

    Map<BlockPos, TempSnapshot> snapshots = TEMPERATURE_CACHE.computeIfAbsent(level.dimension(), dim -> new HashMap<>());
    int tickSpeedMultiplier = 1 + level.getGameRules().getInt(GameRules.RULE_RANDOMTICKING) / 20;

    BlockPos segment = new BlockPos((pos.getX() >> 3) << 3,
                                    (pos.getY() >> 3) << 3,
                                    (pos.getZ() >> 3) << 3);

    // Use cached value if not forced update
    if (!forceUpdate)
    {
        int interval = sensitive ? 200 : 1000;
        TempSnapshot snapshot = snapshots.get(segment);
        if (snapshot != null)
        {
            long gameTime = level.getGameTime();
            if (gameTime - snapshot.timestamp < interval / tickSpeedMultiplier)
            {   return snapshot.temperature();
            }
        }
    }

    /* Get temperature based on dummy entity */
    // Init dummy at this location
    DummyEntity dummy = getDummyEntity(level);
    dummy.setPos(CSMath.getCenterPos(pos));
    // Get modifiers
    List<TempModifier> modifiers = new ArrayList<>(Temperature.getModifiers(dummy, Temperature.Trait.WORLD));

    // Get insulation from hearths
    InsulationSnapshot maxCoolingHeating = getInsulationAt(level, pos, 2);
    if (maxCoolingHeating.cooling() > 0)
    {   modifiers.add(new FrigidnessTempModifier(maxCoolingHeating.cooling()));
    }
    if (maxCoolingHeating.heating() > 0)
    {   modifiers.add(new WarmthTempModifier(maxCoolingHeating.heating()));
    }
    // Get & store temperature
    double tempAt = Temperature.apply(0, dummy, Temperature.Trait.WORLD, modifiers, true);
    snapshots.put(segment, new TempSnapshot(level.getGameTime(), tempAt));

    return tempAt;
}

ENTITY_SPAWN_BIOMES = addSettingWithRegistries(ColdSweat.createKey("entity_spawn_biomes"), RegistryMultiMap::new, (holder, registryAccess) ->
{
    // Function to read biomes from configs and put them in the config settings
    BiConsumer<List<? extends List<?>>, EntityType<?>> configReader = (configBiomes, entityType) ->
    {
        Multimap<Holder<Biome>, SpawnBiomeData> dataMap = ConfigHelper.getRegistryMultimap(configBiomes, registryAccess, Registries.BIOME,
                                                                                           toml -> SpawnBiomeData.fromToml(toml, entityType, registryAccess), data -> data.biomes());
        ConfigLoadingHandler.modifyEntries(dataMap, ModRegistries.ENTITY_SPAWN_BIOME_DATA);

        holder.get(registryAccess).putAll(dataMap);
    };

    // Parse goat and chameleon biomes
    configReader.accept(EntitySettingsConfig.CHAMELEON_SPAWN_BIOMES.get(), ModEntities.CHAMELEON);
    configReader.accept(EntitySettingsConfig.GOAT_SPAWN_BIOMES.get(), EntityType.GOAT);
});

@Nullable
public static SpawnBiomeData fromToml(List<?> entry, EntityType<?> entityType, RegistryAccess registryAccess)
{
    if (entry.size() < 2)
    {   ColdSweat.LOGGER.error("Error parsing entity spawn biome config: not enough arguments");
        return null;
    }
    NegatableList<Either<TagKey<Biome>, OptionalHolder<Biome>>> biomes = ConfigHelper.parseRegistryItems(Registries.BIOME, registryAccess, (String) entry.get(0));
    if (biomes.isEmpty()) return null;

    SpawnBiomeData result =  new SpawnBiomeData(biomes, new NegatableList<>(Either.right(entityType)),
                                                MobCategory.CREATURE, ((Number) entry.get(1)).intValue(),
                                                new IntegerBounds(1, 1), new NegatableList<>());
    result.setConfigType(Type.TOML);
    return result;
}

